const panels=document.querySelector('#panels');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row=(a,b='',sub='')=>`<div class="row"><div>${a}${sub?`<small>${sub}</small>`:''}</div><span class="count">${b}</span></div>`;
const panel=(title,body,wide=false)=>{let e=document.createElement('section');e.className='panel'+(wide?' wide':'');e.id=title.replaceAll(' ','-');e.innerHTML=`<h2>${title}</h2><div class="body">${body}</div>`;panels.append(e)};
