const chart=(bars=false)=>`<svg class="chart" viewBox="0 0 400 160" role="img" aria-label="${bars?'Daily alerts by severity':'Exposure score over 30 days'}"><path d="M0 30H400 M0 70H400 M0 110H400 M0 150H400" stroke="#262932" fill="none"/>${bars?Array.from({length:30},(_,i)=>{let h=15+(i*37%100);return `<rect x="${i*13+3}" y="${150-h}" width="8" height="${h}" fill="${i%4===0?'#fa426d':'#e5ba46'}" opacity=".8"/>`}).join(''):'<path d="M0 125L15 128L30 116L45 120L60 105L75 110L90 98L105 103L120 84L135 86L150 71L165 78L180 60L195 65L210 50L225 70L240 80L255 65L270 85L285 84L300 94L315 101L330 96L345 108L360 94L380 90L400 96" stroke="#e5ba46" stroke-width="3" fill="none"/>'}</svg><div class="axis"><span>08-13</span><span>08-22</span><span>09-01</span><span>09-10</span></div>`;
