const dialog=document.querySelector('#dialog');function modal(title,html){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=html;dialog.showModal()}document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});let toastTimer;function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3500)}
document.querySelector('#menu').onclick=()=>document.querySelector('#nav').hidden=!document.querySelector('#nav').hidden;document.querySelectorAll('aside a').forEach(a=>a.onclick=()=>document.querySelector('#nav').hidden=true);document.querySelector('#theme').onclick=()=>document.body.classList.toggle('light');document.querySelector('#layout').onchange=e=>document.body.classList.toggle('compact',e.target.selectedIndex===1);
document.querySelector('#customize').onclick=()=>{modal('Customize dashboard',Array.from(panels.children).map(p=>`<label class="check"><input type="checkbox" data-panel="${p.id}" ${p.hidden?'':'checked'}>${p.querySelector('h2').textContent}</label>`).join(''));dialog.querySelectorAll('[data-panel]').forEach(c=>c.onchange=()=>document.getElementById(c.dataset.panel).hidden=!c.checked)};
function search(){modal('Jump to panel','<input id="query" placeholder="Search dashboard…" style="width:100%"><div id="results"></div>');const q=document.querySelector('#query');const update=()=>{document.querySelector('#results').innerHTML=Array.from(panels.children).filter(p=>p.id.toLowerCase().includes(q.value.toLowerCase().replaceAll(' ','-'))).map(p=>`<div class="row"><button data-jump="${p.id}">${p.querySelector('h2').textContent}</button></div>`).join('');dialog.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{dialog.close();let p=document.getElementById(b.dataset.jump);p.hidden=false;p.scrollIntoView({behavior:'smooth',block:'center'})})};q.oninput=update;update();q.focus()}document.querySelector('#search').onclick=search;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if(!dialog.open)search()}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action],[data-module]');if(!b)return;if(b.dataset.module){const m=modules.find(x=>x[0]===b.dataset.module);modal(m[0],`<div class="big">${m[1]}</div><p>${m[2]}</p><p>Demo exposure findings for Demo Corp.</p>`);return}switch(b.dataset.action){case 'refresh':document.querySelector('#updated').textContent='Refreshed just now · demo data';toast('Dashboard refreshed');break;case 'report':modal('Demo Corp exposure report','<p>Exposure score: 40 / 100 · Grade C</p>'+row('Open alerts','145')+row('Monitored assets','68')+row('Leaked credentials','43')+'<p>Priority: triage high-risk alerts and patch critical vulnerabilities.</p><button data-action="download">Download report</button>');break;case 'download':{const blob=new Blob(['Demo Corp — Demo Exposure Report\nExposure: 40/100 (C)\nOpen alerts: 145\nMonitored assets: 68\nLeaked credentials: 43\nSample data only.'],{type:'text/plain'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='demo-corp-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break}case 'scan':b.disabled=true;document.querySelector('#scan-status').textContent='Simulating asset scan…';setTimeout(()=>{b.disabled=false;document.querySelector('#scan-status').textContent='Demo scan complete · 68 monitored assets';document.querySelector('#scan-date').textContent=new Date().toLocaleString();toast('Demo scan complete')},1800);break;case 'generate':document.querySelector('#narrative').innerHTML='<ul><li>Exposure remains at 40/100, grade C.</li><li>145 open alerts require triage.</li><li>Two critical vulnerabilities are a patching priority.</li><li>Brand monitoring found active look-alike domains.</li><li>Improve security headers and rotate exposed credentials.</li></ul>';b.disabled=true;break}});
